from pathlib import Path
import json,numpy as np
LAB=Path(__file__).resolve().parent.parent;OUT=LAB.parent.parent/'outputs/neural-stimulus/update-policy'
def dump(p,v):p.write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
def main():
 run=LAB/'results/p62-feedback-acquired-update-reuse-001';s=json.loads((run/'summary.json').read_text());c=s['config'];parent=LAB/'results'/c['parent'];ps=json.loads((parent/'summary.json').read_text());choices=json.loads((run/'selections.json').read_text());allcases=[]
 for label in c['models']:
  cross=json.loads((parent/'models'/label/'decisions.json').read_text());desc=json.loads((parent/'models'/label/'targets.json').read_text());multi=np.array([r['degree']>=2 and r['distinct_lags']>=2 for r in desc])
  for case in range(6):
   choice=next(r for r in choices if r['model']==label and r['case']==case);rows=[r for r in s['results'] if r['model']==label and r['case']==case];base=[next(r for r in rows if r['block']==b and r['slot']==0) for b in range(2)];br=np.array([r['r2'] for r in base]);prior=np.zeros(143,bool);prior[choice['prior_old_ids']]=True;old=prior&(br.min(0)>=.5);bc=np.array([r['nonlinear_temporal_capacity'] for r in base]);historybase=[next(r for r in ps['results'] if r['model']==label and r['case']==case and r['slot']==0 and r['block']==b) for b in range(2)];hbr=np.array([r['r2'] for r in historybase]);records=[]
   for slot in range(7):
    rr=[next(r for r in rows if r['block']==b and r['slot']==slot) for b in range(2)];cap=np.array([r['nonlinear_temporal_capacity'] for r in rr]);delta=cap-bc;rel=delta/np.maximum(bc,.25);nr=np.array([r['r2'] for r in rr]);tr=br if slot==0 else np.array([r['transported_old_r2'] for r in rr]);dr=np.array([r['direct_old_r2'] for r in rr]);kept=old&(tr.min(0)>=.5);hist=[next(r for r in ps['results'] if r['model']==label and r['case']==case and r['slot']==slot and r['block']==b) for b in range(2)];hnr=np.array([r['r2'] for r in hist]);new=multi&(nr.min(0)>=.5)&(hnr.min(0)>=.5)&(br.max(0)<.5)&(hbr.max(0)<.5);joint=bool(slot and old.sum()>0 and all(r['bounded'] for r in base+rr) and min(rel)>=c['quality_acceptance'] and kept.sum()==old.sum())
    records.append(dict(slot=slot,kind=rr[0]['kind'],fraction=rr[0]['fraction'],capacity=cap.tolist(),delta=delta.tolist(),relative_delta=rel.tolist(),eligible_old=int(old.sum()),prior_old=int(prior.sum()),baseline_prior_retained=int(old.sum()),retained_old=int(kept.sum()),prior_retained_unfiltered=int(sum(prior&(tr.min(0)>=.5))),direct_retained_old=int(sum(old&(dr.min(0)>=.5))),lost_ids=np.flatnonzero(old&~kept).tolist(),all_old_retained=bool(old.sum()>0 and kept.sum()==old.sum()),joint_success=joint,new_reliable_nonlinear_ids=np.flatnonzero(new).tolist(),bounded=all(r['bounded'] for r in rr)))
   avail=[r for r in records[1:5] if r['joint_success']];oracle=max(avail,key=lambda r:min(r['relative_delta'])) if avail else records[0];allcases.append(dict(model=label,case=case,seed=choice['seed'],selected_slot=choice['selected_slot'],baseline_capacity=bc.tolist(),feedback=records[choice['selected_slot']],cross_chart=records[cross[case]['selected_slot']],fixed=records[3],random=records[5],oracle=oracle,oracle_available=bool(avail),candidates=records))
 aggregate=[]
 for label in [*c['models'],'pooled']:
  cases=[r for r in allcases if label=='pooled' or r['model']==label];arms={}
  for arm in ['feedback','cross_chart','fixed','random','oracle']:
   rs=[r[arm] for r in cases];arms[arm]=dict(updates=sum(r['slot']!=0 for r in rs),mean_delta=np.mean([r['delta'] for r in rs],0).tolist(),mean_relative_delta=np.mean([r['relative_delta'] for r in rs],0).tolist(),joint_successes=sum(r['joint_success'] for r in rs),complete_retention_cases=sum(r['all_old_retained'] for r in rs),nonempty_reference_cases=sum(r['eligible_old']>0 for r in rs),eligible_old=sum(r['eligible_old'] for r in rs),retained_old=sum(r['retained_old'] for r in rs),prior_old=sum(r['prior_old'] for r in rs),prior_retained_unfiltered=sum(r['prior_retained_unfiltered'] for r in rs),direct_retained_old=sum(r['direct_retained_old'] for r in rs),new_reliable_nonlinear_instances=sum(len(r['new_reliable_nonlinear_ids']) for r in rs))
  aggregate.append(dict(model=label,charts=len(cases),oracle_opportunity_charts=sum(r['oracle_available'] for r in cases),arms=arms))
 p=aggregate[-1]['arms']['feedback'];positive=bool(p['updates'] and min(p['mean_delta'])>0 and p['joint_successes']);report=dict(question='Can own experiential feedback acquire a retained execution/interface pair for later input experience?',criterion_met=positive,aggregate=aggregate,cases=allcases,scope='Choices learned from P61 feedback on these same twelve runtime contexts, then sealed before two untouched P62 streams. Original model weights, source-fitted interfaces and readout programs stay fixed. This is input-stream reuse, distinct from unseen-chart P61 transfer.')
 OUT.mkdir(exist_ok=True,parents=True);dump(OUT/'feedback-analysis.json',report);lines=['P62: feedback-acquired execution/interface reuse','',f'Prespecified positive acquisition/reuse criterion met: {positive}','']
 for m in aggregate:
  lines.append(f"{m['model']}: {m['charts']} contexts, {m['oracle_opportunity_charts']} fresh joint-success opportunities")
  for arm,a in m['arms'].items():lines.append(f"  {arm}: updates={a['updates']}; delta={a['mean_delta']}; joint={a['joint_successes']}; retained={a['retained_old']}/{a['eligible_old']}; prior-unfiltered={a['prior_retained_unfiltered']}/{a['prior_old']}; new reliable nonlinear instances={a['new_reliable_nonlinear_instances']}")
 lines+=['','All feedback-acquired choices:']
 for r in allcases:
  a=r['feedback'];lines.append(f"  {r['model']} seed{r['seed']}: {a['fraction']:+.0%}; delta={a['delta']}; retained={a['retained_old']}/{a['eligible_old']}; joint={a['joint_success']}")
 lines+=['',report['scope']];(OUT/'FEEDBACK-RESULTS.txt').write_text('\n'.join(lines)+'\n');print('\n'.join(lines))
 ledger=json.loads((OUT/'cost-ledger.json').read_text());ledger['p62_additional_native_sequences']=sum(m['native_work']['sequences'] for m in s['models']);ledger['p62_models']=s['models'];ledger['p62_choice_seconds']=s['selection_seconds'];ledger['p61_p62_new_native_sequences_before_verification']=ledger['new_native_sequences']+ledger['p62_additional_native_sequences'];dump(OUT/'cost-ledger.json',ledger)
if __name__=='__main__':main()
